<template><div>
<div class="page-head"><div><h1>题库</h1><p class="muted">筛选、编辑、删除、AI 一键生成</p></div><button @click="load">刷新</button></div>
<div class="panel"><div class="row"><label>年龄<select v-model="filter.ageGroupId"><option :value="null">全部</option><option v-for="x in t.ageGroups" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>学科<select v-model="filter.subjectId"><option :value="null">全部</option><option v-for="x in t.subjects" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>题型<select v-model="filter.type"><option value="">全部</option><option v-for="x in t.questionTypes" :key="x.code" :value="x.code">{{x.name}}</option></select></label><label>方式<select v-model="filter.answerMode"><option value="">全部</option><option value="voice">跟读</option><option value="choice">选择</option></select></label><button @click="load">筛选</button></div></div>
<div class="panel"><h2>AI 一键生成</h2><div class="row"><label>题型<select v-model="gen.questionType"><option v-for="x in t.questionTypes" :key="x.code" :value="x.code">{{x.name}}</option></select></label><label>年龄<select v-model="gen.ageGroupId"><option :value="null">未指定</option><option v-for="x in t.ageGroups" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>学科<select v-model="gen.subjectId"><option :value="null">未指定</option><option v-for="x in t.subjects" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>素材<select v-model="gen.materialId"><option value="">无/自动</option><option v-for="m in materials" :key="m.sha256" :value="m.sha256">{{m.title}}</option></select></label><label>数量<input type="number" v-model.number="gen.count" min="1" max="20" style="width:80px"></label><button @click="generate">生成草稿</button></div><p class="muted" v-if="job">任务 {{ job.id }} · {{ job.status }} <span v-if="job.error">· {{ job.error }}</span></p></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>题目</th><th>分类</th><th>题型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="q in items" :key="q.id"><td><strong>{{q.prompt}}</strong><div class="muted">{{q.answer}} · #{{q.id}}</div></td><td>{{ ageName(q.ageGroupId) }} / {{ subjectName(q.subjectId) }}</td><td>{{q.type}} · {{q.answerMode}}</td><td>{{q.status}}</td><td class="row"><button class="small ghost" @click="activate(q)" v-if="q.status!=='active'">启用</button><button class="small ghost" @click="edit(q)">编辑</button><button class="small danger" @click="remove(q)">删除</button></td></tr></tbody></table></div><p v-if="!items.length" class="muted">暂无题目</p></div>
<div v-if="editing" class="panel"><h2>编辑题目 #{{editing.id}}</h2><div class="row"><input class="grow" v-model="editing.prompt" placeholder="题干"><input class="grow" v-model="editing.answer" placeholder="答案"></div><div class="row"><label>年龄<select v-model="editing.ageGroupId"><option :value="null">未分类</option><option v-for="x in t.ageGroups" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>学科<select v-model="editing.subjectId"><option :value="null">未分类</option><option v-for="x in t.subjects" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>选项（JSON 数组）<input v-model="optionsText" placeholder='["A","B"]'></label><button @click="save">保存</button><button class="ghost" @click="editing=null">取消</button></div></div>
<div class="toast" v-if="toast">{{toast}}</div></div></template>
<script setup>
import { reactive, ref, onMounted } from 'vue'
import { api } from '../api'
const t=ref({ageGroups:[],subjects:[],questionTypes:[]}); const materials=ref([]); const items=ref([]); const filter=reactive({ageGroupId:null,subjectId:null,type:'',answerMode:''}); const gen=reactive({questionType:'word_image',ageGroupId:null,subjectId:null,materialId:'',count:5}); const editing=ref(null); const optionsText=ref(''); const job=ref(null); const toast=ref('')
function ageName(id){return t.value.ageGroups.find(x=>x.id===id)?.name||'未分类'} function subjectName(id){return t.value.subjects.find(x=>x.id===id)?.name||'未分类'}
async function load(){ const qs=new URLSearchParams(); for(const [k,v] of Object.entries(filter)) if(v) qs.set(k,v); const d=await api('/api/v1/admin/questions?'+qs); items.value=d.items }
async function generate(){ try{ const body={questionType:gen.questionType,ageGroupId:gen.ageGroupId,subjectId:gen.subjectId,count:gen.count,materialId:gen.materialId||null}; job.value=(await api('/api/v1/admin/generate',{method:'POST',body})).job; await load() }catch(e){toast.value=e.message} }
function edit(q){ editing.value={...q}; optionsText.value=JSON.stringify(q.options||[]) }
async function save(){ try{ const opts=JSON.parse(optionsText.value||'[]'); await api('/api/v1/admin/questions/'+editing.value.id,{method:'PATCH',body:{prompt:editing.value.prompt,answer:editing.value.answer,ageGroupId:editing.value.ageGroupId,subjectId:editing.value.subjectId,options:opts}}); editing.value=null; await load() }catch(e){toast.value=e.message} }
async function activate(q){ try{ await api('/api/v1/admin/questions/'+q.id+'/status',{method:'POST',body:{status:'active'}}); await load() }catch(e){toast.value=e.message} }
async function remove(q){ if(!confirm('删除题目 #'+q.id+'？')) return; try{ await api('/api/v1/admin/questions/'+q.id,{method:'DELETE'}); await load() }catch(e){toast.value=e.message} }
onMounted(async()=>{ try{ t.value=await api('/api/v1/admin/taxonomies'); materials.value=(await api('/api/v1/admin/materials?limit=200')).items; await load() }catch(e){toast.value=e.message} })
</script>
